const D = { energy: .55, scale: 1, density: .55, speed: 1, tide: .45, haze: .6, hue: 28, x: .5, y: .42, style: 'lowlight', act: 'ebb', seed: 0, alpha: 1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 28;
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const sh = c => [hw(c[0] + ho), c[1], c[2]];

// ---------------- style table: rendering philosophy, not hue swaps ----------------
const STY = {
  // large-format photograph at the bottom of the light: cold sky, one low warm band
  lowlight:  { skyT:[212,26,44], skyM:[206,20,58], skyL:[26,34,72], mudH:[30,12,40], mudL:[26,14,20],
               wat:[204,16,74], glint:[36,26,92], grain:26, ripple:.9, mode:'tonal' },
  // albumen / sepia plate — warm monochrome, heavy grain, printed vignette
  sepia:     { skyT:[32,16,50], skyM:[34,20,64], skyL:[36,30,78], mudH:[32,20,38], mudL:[30,24,17],
               wat:[36,14,76], glint:[40,18,94], grain:44, ripple:1.1, mode:'tonal' },
  // moonlit nocturne — near-monochrome dark key, silver water, no warm band at all
  nocturne:  { skyT:[228,44,22], skyM:[220,34,34], skyL:[196,18,50], mudH:[214,20,24], mudL:[224,26,11],
               wat:[198,10,66], glint:[190,6,88], grain:20, ripple:.7, mode:'tonal' },
  // ABSTRACTED: SAR radar backscatter — water is a black specular void, mud speckles bright
  radar:     { skyT:[150,0,6], skyM:[150,0,9], skyL:[150,0,13], mudH:[80,52,62], mudL:[86,60,28],
               wat:[150,0,4], glint:[70,30,96], grain:70, ripple:1.4, mode:'radar' },
  // ABSTRACTED: survey chart — drafting ground, pure contour line, no tonal mass
  contour:   { skyT:[218,58,21], skyM:[218,52,26], skyL:[216,46,31], mudH:[214,44,27], mudL:[216,50,20],
               wat:[188,52,72], glint:[186,40,96], grain:8, ripple:1, mode:'line' }
};
const st = STY[P.style] || STY.lowlight;

const hy = height * P.y;              // horizon
const cx = width * P.x;
const en = Math.max(0, Math.min(1, P.energy));
const hz = Math.max(0, Math.min(1, P.haze));
const key = width + 'x' + height + '|' + P.style + '|' + P.seed + '|' + Math.round(P.hue) + '|' + P.scale.toFixed(2) + '|' + P.y.toFixed(3) + '|' + P.x.toFixed(3);

// ---------------- build cached strata ----------------
if (!S.sky || S.key !== key) {
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(w, h); g.colorMode(g.HSB, 360, 100, 100, 100); return g; };
  if (S.sky) { S.sky.remove(); S.cl0.remove(); S.cl1.remove(); S.gnd.remove(); }
  S.sky = mk(W, H); S.cl0 = mk(W, Math.max(2, Math.ceil(hy + u * .06)));
  S.cl1 = mk(W, Math.max(2, Math.ceil(hy + u * .06))); S.gnd = mk(W, H);

  // --- sky: banded gradient, warm compression at the horizon (aerial perspective) ---
  const g = S.sky; g.noStroke();
  const cT = sh(st.skyT), cM = sh(st.skyM), cL = sh(st.skyL);
  for (let yy = 0; yy < H; yy++) {
    const f = Math.min(1, yy / Math.max(1, hy));
    const c = f < .62 ? L3(cT, cM, f / .62) : L3(cM, cL, (f - .62) / .38);
    g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1);
  }

  // --- two tileable cloud strata (drawn 3x so they wrap seamlessly when scrolled) ---
  const bank = (gg, n, yc, spread, thick, alp, val, sat) => {
    gg.noStroke();
    for (let i = 0; i < n; i++) {
      const bx = fr(i * 5 + 11) * W;
      const by = yc + (fr(i * 5 + 12) - .5) * spread;
      const bw = u * (.18 + fr(i * 5 + 13) * .55) * (1 + P.scale * .3);
      const bh = thick * (.5 + fr(i * 5 + 14) * .9);
      const cc = sh([st.skyL[0], sat, val]);
      for (let rep = -1; rep <= 1; rep++)
        for (let k = 0; k < 4; k++) {
          gg.fill(cc[0], cc[1] * (1 - k * .12), cc[2] + k * 3, alp * (1 - k * .18));
          gg.ellipse(bx + rep * W, by + k * bh * .18, bw * (1 - k * .13), bh * (1 - k * .1));
        }
    }
  };
  if (st.mode === 'line') {
    // drafting ground: clouds become dashed isobars rather than mass
    for (const [gg, n, yc] of [[S.cl0, 5, hy * .34], [S.cl1, 4, hy * .66]]) {
      gg.noFill(); gg.strokeWeight(Math.max(1, u * .0016));
      for (let i = 0; i < n; i++) {
        const by = yc + (fr(i * 3 + 21) - .5) * hy * .3;
        gg.stroke(hw(st.wat[0] + ho), st.wat[1], st.wat[2], 30 + fr(i * 3 + 22) * 24);
        for (let rep = -1; rep <= 1; rep++) {
          gg.beginShape();
          for (let xx = 0; xx <= W; xx += 12)
            gg.vertex(xx + rep * W, by + Math.sin(xx * .006 + i * 2.1 + fr(i) * 6) * u * .018);
          gg.endShape();
        }
      }
    }
  } else if (st.mode === 'radar') {
    bank(S.cl0, 7, hy * .4, hy * .5, u * .05, 9, 22, 0);
    bank(S.cl1, 5, hy * .72, hy * .34, u * .035, 12, 30, 0);
  } else {
    bank(S.cl0, 9, hy * .34, hy * .5, u * .055, 15, st.skyT[2] + 20, st.skyT[1] * .5);
    bank(S.cl1, 7, hy * .70, hy * .30, u * .030, 20, st.skyL[2] + 12, st.skyL[1] * .4);
  }

  // --- ground: mud plane, perspective grain, sand ripples, dendritic creeks ---
  const q = S.gnd; q.noStroke();
  const mH = sh(st.mudH), mL = sh(st.mudL), wc = sh(st.wat);
  const dep = yy => Math.max(.0012, (yy - hy) / Math.max(1, height - hy));   // 0 at horizon -> 1 at camera
  if (st.mode !== 'line') {
    for (let yy = Math.floor(hy); yy < H; yy++) {
      const f = Math.pow(dep(yy), .55);
      const c = L3(mH, mL, f);
      q.fill(c[0], c[1], c[2]); q.rect(0, yy, W, 1);
    }
  } else {
    q.fill(mL[0], mL[1], mL[2]); q.rect(0, hy, W, H - hy);
  }

  // sand ripples: arcs whose spacing collapses toward the horizon
  const nr = Math.floor(70 * st.ripple);
  for (let i = 0; i < nr; i++) {
    const f = Math.pow((i + .5) / nr, 2.1);                  // pack them near the horizon
    const yy = hy + f * (H - hy);
    const d = dep(yy);
    const amp = u * .012 * d * P.scale;
    q.noFill();
    q.strokeWeight(Math.max(.6, u * .0016 * d * 2.4 * P.scale));
    if (st.mode === 'line') q.stroke(hw(st.wat[0] + ho), st.wat[1] * .7, st.wat[2] * .5, 22);
    else q.stroke(mL[0], mL[1] * .8, mL[2] + 16 + fr(i) * 10, 16 + 12 * d);
    q.beginShape();
    for (let xx = -20; xx <= W + 20; xx += Math.max(6, 14 * d)) {
      const w1 = Math.sin(xx * .009 / P.scale + i * .7) + .6 * Math.sin(xx * .023 / P.scale + i * 1.9);
      q.vertex(xx, yy + w1 * amp);
    }
    q.endShape();
  }

  // perspective grain — dense and fine up close, sparse and hazed far off
  const ng = st.mode === 'line' ? 0 : Math.floor(2600 * (st.grain / 40));
  q.noStroke();
  for (let i = 0; i < ng; i++) {
    const f = Math.pow(fr(i * 3 + 101), 2.4);
    const yy = hy + f * (H - hy), xx = fr(i * 3 + 102) * W, d = dep(yy);
    const v = (fr(i * 3 + 103) - .5) * st.grain;
    const c = L3(mH, mL, Math.pow(d, .55));
    q.fill(c[0], c[1], Math.max(2, c[2] + v), 34 + 30 * d);
    const r = Math.max(.7, u * .0022 * d * 3);
    q.rect(xx, yy, r, r * .7);
  }

  // dendritic drainage creeks — bright, they hold the sky
  const branch = (x0, y0, ang, len, wid, dpt, id) => {
    if (dpt > 6 || len < u * .008 || y0 < hy + 2) return;
    let xx = x0, yy = y0, a = ang;
    const segs = 5 + (dpt < 2 ? 4 : 0);
    q.noFill();
    for (let s = 0; s < segs; s++) {
      a += (fr(id * 17 + s * 3 + dpt) - .5) * .5;
      const nx = xx + Math.cos(a) * len / segs, ny = yy + Math.sin(a) * len / segs;
      if (ny < hy + 1) break;
      const d = dep(ny);
      const w2 = Math.max(.5, wid * (.35 + d * .9));
      q.strokeWeight(w2);
      if (st.mode === 'line') q.stroke(wc[0], wc[1], wc[2], 60);
      else if (st.mode === 'radar') q.stroke(wc[0], 0, 4, 92);
      else q.stroke(wc[0], wc[1] * (.5 + .5 * d), wc[2] - 8 + 14 * d, 62 + 26 * d);
      q.line(xx, yy, nx, ny);
      // wet margin — the darkened lip of the channel
      if (st.mode === 'tonal') {
        q.strokeWeight(w2 * 2.6); q.stroke(mL[0], mL[1] + 10, Math.max(3, mL[2] - 7), 16);
        q.line(xx, yy, nx, ny);
        q.strokeWeight(w2); q.stroke(wc[0], wc[1] * (.5 + .5 * d), wc[2] - 8 + 14 * d, 62 + 26 * d);
        q.line(xx, yy, nx, ny);
      }
      xx = nx; yy = ny;
      if (s === segs - 2 && dpt < 6) {
        branch(xx, yy, a - .55 - fr(id + 7) * .5, len * .62, wid * .6, dpt + 1, id * 3 + 1);
        branch(xx, yy, a + .5 + fr(id + 9) * .5, len * .6, wid * .58, dpt + 1, id * 3 + 2);
      }
    }
  };
  const nc = 3 + Math.floor(P.density * 4);
  for (let i = 0; i < nc; i++) {
    const mx = W * (.08 + fr(i * 11 + 3) * .84);
    branch(mx, H + u * .02, -Math.PI / 2 + (fr(i * 11 + 4) - .5) * .7,
           (H - hy) * (.42 + fr(i * 11 + 5) * .3), Math.max(1.4, u * .009 * P.scale), 0, i * 31 + 5);
  }
  S.key = key;
}

// ---------------- act: the tide programme, indexed off the section arc ----------------
const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const ACT = { ebb: { pull: .18 + sec * .07, lift: 0 }, flood: { pull: .82 - sec * .07, lift: .1 }, slack: { pull: .5, lift: .04 } };
const act = ACT[P.act] || ACT.ebb;

// ---------------- composite ----------------
noStroke();
image(S.sky, 0, 0);

// cloud strata, scrolled on two incommensurate linear rates (guaranteed motion floor)
const W2 = S.cl0.width;
const scr = (g, px) => { const ox = ((px % W2) + W2) % W2; image(g, ox - W2, 0); image(g, ox, 0); };
scr(S.cl0, -K.t * u * .0042 * P.speed);
scr(S.cl1, -K.t * u * .0113 * P.speed - u * .3);

// horizon haze bank — the value-compression plane that sells the distance
const hazeC = sh(st.mode === 'radar' ? [150, 0, 20] : [st.skyL[0], st.skyL[1] * .5, st.skyL[2] + 6]);
for (let i = 0; i < 4; i++) {
  const dr = Math.sin(K.t * (.031 + i * .017) + i * 2.1) * .5 + .5;
  fill(hazeC[0], hazeC[1], hazeC[2], (7 + 9 * hz) * (1 - i * .16));
  rect(0, hy - u * (.05 + i * .012) - dr * u * .012, width, u * (.10 + i * .045));
}

image(S.gnd, 0, 0);

// --- sheet water: pans of standing water holding the sky, shimmering ---
const dep = yy => Math.max(.0012, (yy - hy) / Math.max(1, height - hy));
const wc = sh(st.wat), gl = sh(st.glint);
const np = Math.floor(10 + P.density * 26);
blendMode(st.mode === 'radar' ? MULTIPLY : BLEND);
for (let i = 0; i < np; i++) {
  const f = Math.pow(fr(i * 7 + 201), 1.9);
  const yy = hy + f * (height - hy);
  const d = dep(yy);
  const px = fr(i * 7 + 202) * width;
  const pw = u * (.06 + fr(i * 7 + 203) * .22) * (.3 + d * 1.5) * P.scale;
  const ph = u * .012 * (.2 + d * 1.6) * P.scale;
  // shimmer: three incommensurate real-time terms, never re-phases at 8s
  const sm = .5 + .5 * (Math.sin(K.t * (.61 + i * .013) + i) * .5 + Math.sin(K.t * 1.43 + i * 2.1) * .32 + Math.sin(K.t * 2.29 + i) * .18);
  const gain = (.5 + .5 * en) * (.55 + .45 * sm) + A.rms * .5;
  if (st.mode === 'radar') { fill(0, 0, 3, 70 + 22 * gain); ellipse(px, yy, pw, ph); continue; }
  if (st.mode === 'line') { noFill(); stroke(wc[0], wc[1], wc[2], 30 + 34 * gain); strokeWeight(Math.max(.7, u * .0012)); ellipse(px, yy, pw, ph); noStroke(); continue; }
  fill(wc[0], wc[1] * (.5 + .5 * d), Math.min(99, wc[2] * (.62 + .3 * gain)), 40 + 34 * d);
  ellipse(px, yy, pw, ph);
  // the specular streak inside the pan
  fill(gl[0], gl[1] * .6, gl[2], (16 + 40 * gain) * (.4 + .6 * en));
  ellipse(px + Math.sin(K.t * .27 + i) * pw * .12, yy, pw * (.3 + .3 * sm), ph * .38);
}
blendMode(BLEND);

// --- the tide edge: a bright creeping line, on slow incommensurate rates ---
const tf = Math.max(0, Math.min(1, P.tide * act.pull + .12 * Math.sin(K.t * .023) + .06 * Math.sin(K.t * .0561 + 1.3)));
const ty = hy + Math.pow(.06 + tf * .9, 1.7) * (height - hy);
const td = dep(ty);
noFill();
for (let L = 0; L < 3; L++) {
  strokeWeight(Math.max(.8, u * (.0018 + L * .0012) * (.4 + td)));
  stroke(gl[0], gl[1] * (.5 - L * .1), gl[2] - L * 8, (st.mode === 'line' ? 40 : 60 + 24 * en) * (1 - L * .28));
  beginShape();
  for (let xx = -10; xx <= width + 10; xx += 9) {
    const wv = Math.sin(xx * .011 + K.t * (.5 + L * .21)) * .6 + Math.sin(xx * .027 - K.t * (.83 + L * .17)) * .3 + Math.sin(xx * .004 + K.t * .13) * .8;
    vertex(xx, ty + L * u * .006 + wv * u * .008 * (.3 + td) * (.5 + en));
  }
  endShape();
}
noStroke();
if (st.mode === 'tonal') { fill(wc[0], wc[1] * .7, wc[2] * .5, 26); rect(0, ty, width, Math.max(2, u * .012 * (.3 + td))); }

// --- distant waders: specks, never characters. Pure silhouette, drifting. ---
const nb = Math.floor(P.density * 9 * (st.mode === 'line' ? 0 : 1));
for (let i = 0; i < nb; i++) {
  const f = .1 + fr(i * 9 + 301) * .5;
  const yy = hy + Math.pow(f, 1.6) * (height - hy) * .8;
  const d = dep(yy);
  const bx = (fr(i * 9 + 302) * width + Math.sin(K.t * (.07 + fr(i * 9 + 303) * .05) + i * 2) * u * .09 + width) % width;
  const bob = Math.sin(K.t * (1.7 + i * .3) + i) * u * .0015;
  fill(st.mode === 'radar' ? 70 : 0, st.mode === 'radar' ? 20 : 0, st.mode === 'radar' ? 92 : 8, 60 + 26 * d);
  ellipse(bx, yy + bob, u * .006 * (.3 + d) * P.scale, u * .004 * (.3 + d) * P.scale);
}

// --- a low sun band / cold moon glow riding the horizon ---
if (st.mode !== 'line' && st.mode !== 'radar') {
  const sx = cx + Math.sin(K.t * .0091) * width * .06;
  const sy = hy - u * (.015 + act.lift * .1);
  const gg = (.45 + .55 * en) * (.7 + .3 * K.swell) + A.lowmid * .3;
  blendMode(ADD);
  for (let i = 4; i >= 0; i--) {
    fill(gl[0], gl[1] * (.7 - i * .1), gl[2], (5 + 7 * gg) * (1 - i * .12));
    ellipse(sx, sy, u * (.10 + i * .30) * (1 + .06 * Math.sin(K.t * .43)), u * (.05 + i * .11));
  }
  blendMode(BLEND);
}

// --- printed vignette / plate edge ---
if (st.mode !== 'radar') {
  const vg = st.mode === 'line' ? 30 : 22 + hz * 20;
  for (let i = 0; i < 5; i++) {
    noFill(); strokeWeight(u * .055);
    stroke(hw(st.mudL[0] + ho), st.mudL[1], st.mode === 'line' ? st.skyT[2] * .5 : 6, vg * (1 - i * .17) * .5);
    rect(-u * .03 + i * u * .03, -u * .03 + i * u * .03, width + u * .06 - i * u * .06, height + u * .06 - i * u * .06);
  }
  noStroke();
}

// --- global veil (alpha = how far the world sits back behind the performers) ---
if (P.alpha < 1) { noStroke(); fill(hw(st.mudL[0] + ho), st.mudL[1] * .5, 4, (1 - P.alpha) * 100); rect(0, 0, width, height); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
